export const GREXAL_PAID_EXECUTION = false;
20→
function parseArgs(argv) {
  const out = { _: [] };
  for (let i = 0; i < argv.length; i++) {
    const cur = argv[i];
    if (cur === '--help' || cur === '-h') {
      out.help = true;
      continue;
    }
    if (cur.startsWith('--') && argv[i + 1] && !argv[i + 1].startsWith('--')) {
30→      out[cur.slice(2)] = argv[++i];
