export const DEFAULT_MAX_DIFF_BYTES = 5 * 1024 * 1024;

const TRAVERSAL = /(^|\/)\.\.(\/|$)/;

/** Unquote a git C-style path token. Labels only — not git-apply. */
export function unquoteGitPath(raw) {
