date -u +%Y-%m-%dT%H:%M:%SZ
PACK=experiments/s109-marketplace-entry-trials/surfaces/grexal/package/agent/pack_evidence.js
BASE=experiments/s109-marketplace-entry-trials/s121
# Re-run CLI after patch; keep acceptance inside experiment tree; do not keep 2MB diff
node "$PACK" --unifiedDiffFile "$BASE/fixtures/diff/malicious-paths.patch" --outDir "$BASE/out/_c4-cli-mal" --acceptanceNotes 'C4 malicious-paths CLI after path-hardening'
echo "mal_exit=$?"
node "$PACK" --unifiedDiffFile "$BASE/fixtures/diff/oversized.patch" --maxDiffBytes 100000 --outDir "$BASE/out/_c4-cli-ovr" --acceptanceNotes 'C4 oversized CLI 100000'
echo "ovr_exit=$?"
rm -f "$BASE/out/_c4-cli-ovr/changes.diff"

node --input-type=module <<'JS'
import fs from 'node:fs';
import { packEvidence } from './experiments/s109-marketplace-entry-trials/surfaces/grexal/package/agent/pack_evidence.js';
import { analyzeUnifiedDiff, isUnsafePath } from './experiments/s109-marketplace-entry-trials/surfaces/grexal/package/lib/diff_analysis.js';

const extra = {
  quoted: 'diff --git "a/../../etc/passwd" "b/../../etc/passwd"\n--- a/../../etc/passwd\n+++ b/../../etc/passwd\n@@ -1 +1 @@\n-x\n+y\n',
  plusPlusOnly: 'diff --git a/safe.txt b/safe.txt\n--- a/safe.txt\n+++ b/../../etc/passwd\n@@ -1 +1 @@\n-x\n+y\n',
  backslash: 'diff --git a/..\\..\\etc\\passwd b/..\\..\\etc\\passwd\n--- a/..\\..\\etc\\passwd\n+++ b/..\\..\\etc\\passwd\n@@ -1 +1 @@\n-x\n+y\n',
  noPrefix: 'diff --git ../../etc/passwd ../../etc/passwd\n--- ../../etc/passwd\n+++ ../../etc/passwd\n@@ -1 +1 @@\n-x\n+y\n',
  renameTo: 'diff --git a/safe.txt b/../../etc/shadow\nsimilarity index 100%\nrename from safe.txt\nrename to ../../etc/shadow\n',
  devNullAdd: 'diff --git a/new.txt b/new.txt\nnew file mode 100644\n--- /dev/null\n+++ b/new.txt\n@@ -0,0 +1 @@\n+hi\n',
};
const after = {};
for (const [k, text] of Object.entries(extra)) {
  const r = packEvidence({ unifiedDiff: text });
  after[k] = {
    structuralChecksPass: r.structuralChecksPass,
    unsafePaths: r.acceptanceReport.unsafePaths,
    files: r.evidencePack.analysis.files.map(f => ({ aPath: f.aPath, bPath: f.bPath })),
  };
}
const mal = packEvidence({ unifiedDiff: fs.readFileSync('experiments/s109-marketplace-entry-trials/s121/fixtures/diff/malicious-paths.patch','utf8') });
const ovr = packEvidence({ unifiedDiff: fs.readFileSync('experiments/s109-marketplace-entry-trials/s121/fixtures/diff/oversized.patch','utf8'), maxDiffBytes: 100000 });
const ovrDef = packEvidence({ unifiedDiff: fs.readFileSync('experiments/s109-marketplace-entry-trials/s121/fixtures/diff/oversized.patch','utf8') });
console.log(JSON.stringify({
  malUnsafe: mal.acceptanceReport.unsafePaths,
  malPass: mal.structuralChecksPass,
  ovrPass: ovr.structuralChecksPass,
  ovrSize: ovr.acceptanceReport.checks.find(c=>c.id==='diff-size-limit'),
  ovrDefPass: ovrDef.structuralChecksPass,
  extraAfter: after,
  devNullIsUnsafe: isUnsafePath('/dev/null'),
  traversalIsUnsafe: isUnsafePath('../../etc/passwd'),
}, null, 2));
JS

